{modal?.kind==='validation'&&<>{f('name','Revisión','text',null,true)}{f('description','Descripción','textarea')}{f('status','Estado','text',['Pendiente','En curso','Completada'])}<h3>Checklist</h3>{draft.checklist?.map((c:any,i:number)=><div className="checklist" key={i}><input type="checkbox" checked={c.done} onChange={e=>set('checklist',draft.checklist.map((x:any,k:number)=>k===i?{...x,done:e.target.checked}:x))}/><input aria-label="Ítem" value={c.name} onChange={e=>set('checklist',draft.checklist.map((x:any,k:number)=>k===i?{...x,name:e.target.value}:x))}/><button type="button" onClick={()=>set('checklist',draft.checklist.filter((_:any,k:number)=>k!==i))}><X size={14}/></button></div>)}<button type="button" onClick={()=>set('checklist',[...(draft.checklist||[]),{name:'',done:false}])}>+ Ítem</button></>}
{modal?.kind==='area'&&<>{f('name','Área o entregable','text',null,true)}{f('description','Intervención y resultado esperado','textarea')}{f('status','Estado','text',['Pendiente','En curso','Operativo','Listo'])}{f('priority','Prioridad','text',['Baja','Normal','Alta'])}{f('notes','Notas')}</>}
{modal?.kind==='task'&&<>{f('name','Tarea','text',null,true)}{f('description','Descripción','textarea')}{f('output','Entregable esperado','textarea')}{f('who','Participantes (ej. Diploy + cliente)')}{f('stage','Etapa','text',p?.stages.map((s:any)=>({value:s.id,label:s.name})))}{f('area','Área del alcance','text',[{value:'',label:'Sin área'},...(p?areaNames(p):[]).map((a:string)=>({value:a,label:a}))])}{f('owner','Responsable','text',[...owners,'Cliente'])}{f('start','Fecha de inicio','date')}{f('due','Fecha límite','date')}{f('priority','Prioridad','text',['Baja','Normal','Media','Alta'])}{f('status','Estado','text',taskStatuses)}<h3>Checklist</h3>{draft.checklist?.map((c:any,i:number)=><div className="checklist" key={i}><input type="checkbox" checked={c.done} onChange={e=>set('checklist',draft.checklist.map((x:any,k:number)=>k===i?{...x,done:e.target.checked}:x))}/><input aria-label="Subtarea" value={c.name} onChange={e=>set('checklist',draft.checklist.map((x:any,k:number)=>k===i?{...x,name:e.target.value}:x))}/><button type="button" onClick={()=>set('checklist',draft.checklist.filter((_:any,k:number)=>k!==i))}><X size={14}/></button></div>)}<button type="button" onClick={()=>set('checklist',[...(draft.checklist||[]),{name:'',done:false}])}>+ Subtarea</button><h3>Comentarios</h3>{draft.comments?.map((c:any,i:number)=><p className="comment" key={i}>{c.text}<small>{c.actor} / {new Date(c.date).toLocaleDateString('es-CL')}</small></p>)}<textarea aria-label="Nuevo comentario" value={draft.comment||''} onChange={e=>set('comment',e.target.value)}/><button type="button" onClick={()=>{if(draft.comment?.trim()){set('comments',[...(draft.comments||[]),{text:draft.comment,actor:user,date:new Date().toISOString()}]);set('comment','')}}}>Añadir comentario</button>{f('url','Enlace del archivo','text')}<label className="field">Adjuntar archivo (máx. 20 MB)<input type="file" onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/></label>{draft.fileName&&<p>{draft.fileName}</p>}</>}
{['reference','delivery'].includes(modal?.kind)&&<>{f('name',modal?.kind==='reference'?'Título de referencia':'Nombre','text',null,true)}{f('notes',modal?.kind==='delivery'?'Observaciones del cliente':'Notas','textarea')}{modal?.kind!=='reference'&&f('date','Fecha','date')}{modal?.kind==='reference'&&<>{f('tags','Etiquetas (separadas por coma)')}{f('status','Aprobación','text',['Propuesta','Aprobada'])}</>}{modal?.kind==='delivery'&&<>{f('type','Tipo','text',['Parcial','Final'])}{f('status','Estado','text',['Pendiente','Enviada','En revisión','Aprobada','Con correcciones'])}</>}{<>{f('url','Enlace / archivo','text')}<label className="field">Subir archivo (máx. 20 MB)<input type="file" accept={modal.kind==='reference'?'image/*':undefined} onChange={e=>e.target.files?.[0]&&upload(e.target.files[0])}/></label>{draft.fileName&&<p>{draft.fileName}</p>}</>}</>}
{['payment','expense'].includes(modal?.kind)&&<>{f('project','Proyecto','text',projectOptions,true)}{f('concept','Concepto','text',null,true)}{f('amount','Monto (CLP)','number',null,true)}{f('date',modal.kind==='payment'?'Fecha recibida o programada':'Fecha','date',null,true)}{modal.kind==='payment'&&<>{f('status','Estado','text',['Recibido','Pendiente'])}{f('method','Método','text',['Transferencia','Efectivo','Otro'])}</>}{f('notes','Notas','textarea')}</>}
{modal?.kind==='quote'&&<>{f('name','Nombre de cotización','text',null,true)}{f('project','Proyecto','text',projectOptions,true)}{f('status','Estado','text',['Borrador','Enviada','Aprobada','Rechazada'])}<h3>Servicios</h3>{draft.items?.map((i:any,k:number)=><div className="quote-item" key={k}>{['name','qty','price'].map((key,j)=><label key={key}>{['Servicio','Cantidad','Precio CLP'][j]}<input aria-label={['Servicio','Cantidad','Precio CLP'][j]} required type={j?'number':'text'} min={j===1?1:j===2?0:undefined} value={i[key]} onChange={e=>set('items',draft.items.map((x:any,n:number)=>n===k?{...x,[key]:e.target.value}:x))}/></label>)}<button type="button" disabled={draft.items.length===1} onClick={()=>set('items',draft.items.filter((_:any,n:number)=>n!==k))}><X size={14}/></button></div>)}<button type="button" onClick={()=>set('items',[...draft.items,{name:'',qty:1,price:0}])}>+ Servicio</button>{f('discount','Descuento CLP','number')}<label className="checklist"><input type="checkbox" checked={draft.iva||false} onChange={e=>set('iva',e.target.checked)}/>Aplicar IVA 19%</label><h2>Total {money(quoteTotal(draft))}</h2>{f('notes','Condiciones y notas','textarea')}</>}
